import { useState, useEffect, useCallback } from 'react'
import { ProviderListStyle } from './index.style'
import TableWrapper from '../../../../pagination.style'
import LayoutContentStyle from '../../../../../../../components/utility/layoutContent'
import { Button, Row, Col, Modal } from 'antd'
import { providerListTable } from '../../../constants'
import { showNotification } from '../../../../../../../components/ShowNotification'
import CircularLoader from '../../../../../../../components/CircularLoader'
import { useGetProviderList } from '../../../state/hooks/useProviderState'
import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import ProviderForm from '../../../components/ProviderForm'
import { trimObjectValues } from '../../../../../../../helpers/utility'
import isVNPath from '../../../../../../../helpers/isVNPath'

function ProviderList (props) {
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [filterApply, setFilterApply] = useState('')
  const [isFilterVisible, setIsFilterVisible] = useState('')
  const [providerColumns, setProviderColumns] = useState([])
  const [isChange, setIsChange] = useState(false)
  const [showProviderForm, setShowProviderForm] = useState(false)

  const [{ getProviderListData = [] }, getProviderListRequest] = useGetProviderList()
  const [{ GET_PROVIDER_LIST_LOADER, ADD_PROVIDER_LOADER }
  ] = useLoaderContextValue()

  const [{ GET_PROVIDER_LIST_ERROR, getProviderListStatus },
    dispatchError
  ] = useErrorContextValue()

  const fetchProviderList = useCallback((queryObject) => {
    getProviderListRequest({
      query: {
        ...queryObject
      }
    })
  }, [getProviderListRequest])

  const handleProviderDetailPage = useCallback((id) => {
    // move the customer to Agent
    props.history.push({
      pathname: `/agent${isVNPath() ? '/vn' : ''}/provider/${id}/detail`
    })
  }, [props.history])

  const handleInputChange = useCallback((event, identifier) => {
    setSearchTextQuery({
      ...searchTextQuery,
      [identifier]: event.target.value
    })
    setIsChange(true)
  }, [searchTextQuery])

  const handleSearch = useCallback((e) => {
    e.preventDefault()
    setIsFilterVisible('')
    setFilterApply(isFilterVisible)
    fetchProviderList(trimObjectValues(searchTextQuery))
  }, [searchTextQuery, isFilterVisible, fetchProviderList])

  const getProviderListTable = useCallback(() => {
    return providerListTable({
      handleProviderDetailPage,
      searchTextQuery,
      handleInputChange,
      handleSearch,
      isFilterVisible,
      setIsFilterVisible,
      isChange
    })
  }, [isFilterVisible, isChange, searchTextQuery,
    handleInputChange, handleProviderDetailPage, handleSearch
  ])

  useEffect(() => {
    fetchProviderList({})
  }, [fetchProviderList])

  useEffect(() => {
    setProviderColumns(getProviderListTable())
  }, [isFilterVisible, searchTextQuery, getProviderListData, getProviderListTable])

  useEffect(() => {
    if (getProviderListStatus && GET_PROVIDER_LIST_ERROR) {
      showNotification('error', getProviderListStatus)
      dispatchError(resetError({
        getProviderListStatus: ''
      }))
    }
  }, [getProviderListStatus, GET_PROVIDER_LIST_ERROR,
    dispatchError
  ])

  const handleClearFilter = useCallback(() => {
    setFilterApply('')
    setSearchTextQuery({})
    fetchProviderList({})
  }, [fetchProviderList])

  const handleAddProvider = useCallback(() => {
    setShowProviderForm(true)
  }, [])

  const closeProviderForm = useCallback(() => {
    setShowProviderForm(false)
  }, [])

  return (
    <ProviderListStyle>
      <Modal
        footer={null}
        visible={showProviderForm}
        onCancel={closeProviderForm}
      >
        <ProviderForm onFetchProviderList={fetchProviderList} onCloseProviderForm={closeProviderForm} />
      </Modal>
      <CircularLoader isSpining={GET_PROVIDER_LIST_LOADER || ADD_PROVIDER_LOADER}>
        <LayoutContentStyle>
          <Row type='flex' align='middle' justify='space-between' className='header-row'>
            <Col>
              <h3>Providers List</h3>
            </Col>
            <Col className='clear-filter'>
              <Button
                type='primary'
                onClick={handleAddProvider}
              >
                Add Provider
              </Button>
              &nbsp;&nbsp;&nbsp;
              <Button
                type='primary'
                onClick={handleClearFilter}
                disabled={!filterApply}
              >
                Clear Filter
              </Button>
            </Col>
          </Row>
          <TableWrapper
            columns={providerColumns}
            bordered
            rowKey={record => record.id}
            dataSource={getProviderListData || []}
            loading={GET_PROVIDER_LIST_LOADER}
            className='isoSearchableTable agent-table-data'
          />
        </LayoutContentStyle>
      </CircularLoader>
    </ProviderListStyle>
  )
}

export default ProviderList
